local function dirname(path)
    local p = path:gsub("\\", "/")
    return (p:match("^(.*)/[^/]+$") or ".")
end

local validator = nil
do
    local scriptPath = debug.getinfo(1, "S").source:sub(2)
    if scriptPath:sub(1, 1) ~= "/" and io.popen then
        local p = io.popen("pwd")
        if p then
            local cwd = p:read("*l")
            p:close()
            if cwd and cwd ~= "" then
                scriptPath = cwd .. "/" .. scriptPath
            end
        end
    end

    local scriptDir = dirname(scriptPath)
    local ok, mod = pcall(dofile, scriptDir .. "/../compiler/validator.lua")
    if ok and type(mod) == "table" then
        validator = mod
    end
end

local function normalizeFieldValue(field, value)
    if not field or field.fieldType ~= "output" then
        return value
    end
    if not validator or type(validator.normalize) ~= "function" then
        return value
    end

    local ok, normalized = pcall(validator.normalize, field, value)
    if ok then
        return normalized
    end
    return value
end

local function a_ensure_parser_ready(parser)
    if not parser then
        return false
    end

    if not parser.ready and type(parser.load) == "function" then
        parser.load()
    end

    if type(parser.update) == "function" then
        parser.update()
    end

    return parser.ready == true
end

local function a_find_localizer_for_airport(nav, airport_ident, runway_ident)
    if not nav or type(nav.loc) ~= "table" then
        return nil
    end

    local function normalizeRunway(raw)
        local s = (tostring(raw or ""):gsub("^%s+", ""):gsub("%s+$", "")):upper()
        if s == "" then
            return nil
        end

        if s:sub(1, 2) == "RW" then
            s = s:sub(3)
        end

        local num, suffix = s:match("^(%d%d)([LRC]?)$")
        if not num then
            local single, singleSuffix = s:match("^(%d)([LRC]?)$")
            if single then
                num = "0" .. single
                suffix = singleSuffix
            else
                return nil
            end
        end

        local n = tonumber(num)
        if not n or n < 1 or n > 36 then
            return nil
        end

        return string.format("%02d%s", n, suffix or "")
    end

    local requestedRunway = normalizeRunway(runway_ident)

    -- Iterate deterministically over sorted idents to ensure stable selection of
    -- a fallback localizer when multiple candidates exist for the same airport.
    local idents = {}
    for ident in pairs(nav.loc) do
        idents[#idents + 1] = ident
    end
    table.sort(idents)

    local fallback = nil
    for _, ident in ipairs(idents) do
        local entries = nav.loc[ident]
        for _, loc in ipairs(entries) do
            if loc.airport == airport_ident then
                if requestedRunway and normalizeRunway(loc.runway) == requestedRunway then
                    return loc
                end
                if not fallback then
                    fallback = loc
                end
            end
        end
    end

    return fallback
end

local function a_find_runway_end(apt, airport_ident, runway_ident)
    if not apt or not airport_ident or not runway_ident then
        return nil
    end

    local function normalizeRunway(raw)
        local s = (tostring(raw or ""):gsub("^%s+", ""):gsub("%s+$", "")):upper()
        if s == "" then
            return nil
        end

        if s:sub(1, 2) == "RW" then
            s = s:sub(3)
        end

        local num, suffix = s:match("^(%d%d)([LRC]?)$")
        if not num then
            local single, singleSuffix = s:match("^(%d)([LRC]?)$")
            if single then
                num = "0" .. single
                suffix = singleSuffix
            else
                return nil
            end
        end

        local n = tonumber(num)
        if not n or n < 1 or n > 36 then
            return nil
        end

        return string.format("%02d%s", n, suffix or "")
    end

    local airport = (tostring(airport_ident or ""):gsub("^%s+", ""):gsub("%s+$", "")):upper()
    local runway = normalizeRunway(runway_ident)
    if airport == "" or not runway then
        return nil
    end

    if type(apt.findRunwayEnd) == "function" then
        return apt.findRunwayEnd(airport, runway)
    end

    local byAirportRunway = apt.byAirportRunway
    if type(byAirportRunway) == "table" then
        local list = byAirportRunway[airport .. "|" .. runway]
        if list and #list > 0 then
            return list[1]
        end
    end

    return nil
end

