local function evalDependencyRpn(rpn, values)
    if not rpn or #rpn == 0 then
        return true
    end

    local stack = {}
    for i = 1, #rpn do
        local tok = rpn[i]
        if tok.type == "id" then
            stack[#stack + 1] = not not values[tok.value]
        elseif tok.type == "op" then
            if tok.value == "not" then
                local a = stack[#stack]
                stack[#stack] = not a
            else
                local b = stack[#stack]
                stack[#stack] = nil
                local a = stack[#stack]
                stack[#stack] = nil
                if tok.value == "and" then
                    stack[#stack + 1] = a and b
                else
                    stack[#stack + 1] = a or b
                end
            end
        end
    end

    return not not stack[1]
end

function mainTable.fieldVisible(slot, values)
    local field = mainTable.fieldsBySlot[slot]
    if not field then
        return false
    end
    values = values or {}
    return evalDependencyRpn(field.dependencyRpn, values)
end

function mainTable.runCommand(slot, ...)
    local field = mainTable.fieldsBySlot[slot]
    if not field then
        return nil, "Unknown slot"
    end

    local cmd = field.command
    if cmd == "" or cmd == "none" then
        return nil
    end
    if cmd == "update" then
        return true
    end

    local fn = mainTable.commands[cmd]
    if not fn then
        return nil, "Missing compiled command: " .. tostring(cmd)
    end

    local value = fn(...)
    return normalizeFieldValue(field, value)
end

function mainTable.updateDependency(symbol, context)
    local targets = mainTable.reverseDeps[symbol] or {}
    if not context or type(context.recompute) ~= "function" then
        return targets
    end

    for i = 1, #targets do
        context.recompute(mainTable, targets[i], context)
    end
    return targets
end

return mainTable
